B.aXh=s(["\u26bd Gols dobles","\u26bd Goles dobres","\u26bd Gol bikoitzak","\u26bd Double goals","\u26bd Doppelte Tore","\u26bd Gol doppi","\u26bd Dubbele goals","\u26bd Buts doubles"],t.s)
